        # With equal cores, having no pre-release ranks higher.
        return result or _sign(not a.prerelease, not b.prerelease)
    for x, y in zip(a.prerelease, b.prerelease):
        result = _compare_ident(x, y)
        if result:
            return result
    return _sign(len(a.prerelease), len(b.prerelease))


def _comparators(text: str) -> list[tuple[str, Version]]:
    """Expand one comparator into primitive ``(operator, version)`` pairs."""
    match = _OPERATOR_RE.fullmatch(text)
    op, version = match.group(1) or "=", parse(match.group(2))
    major, minor, patch = version.major, version.minor, version.patch
    if op == "^":
        if major:
            upper = Version(major + 1, 0, 0)
        elif minor:
            upper = Version(0, minor + 1, 0)
        else:
            upper = Version(0, 0, patch + 1)
        return [(">=", version), ("<", upper)]
    if op == "~":
        return [(">=", version), ("<", Version(major, minor + 1, 0))]
    return [(op, version)]


_OPS = {
    "=": lambda r: r == 0,
    ">": lambda r: r > 0,
    ">=": lambda r: r >= 0,
    "<": lambda r: r < 0,
    "<=": lambda r: r <= 0,
}


def satisfies(version: str | Version, range_: str) -> bool:
    """Whether ``version`` is in ``range_``."""
    version = _coerce(version)
    sets = []
    for part in range_.split("||"):
        words = part.split()
        if not words:
            raise ValueError(f"invalid range: {range_!r} (empty comparator set)")
        try:
            sets.append([pair for word in words for pair in _comparators(word)])
        except ValueError:
            raise ValueError(f"invalid range: {range_!r}") from None
    core = (version.major, version.minor, version.patch)
    for comparators in sets:
        if version.prerelease and not any(
            bound.prerelease and (bound.major, bound.minor, bound.patch) == core
            for _, bound in comparators
        ):
            continue
        if all(_OPS[op](compare(version, bound)) for op, bound in comparators):
            return True
    return False
